def triples_sum_to_zero(l: list):
    if len(l) < 3:
        return False

    # Sort the list to enable two-pointer technique
    l.sort()
    n = len(l)

    # Check all possible triplets using three pointers
    for i in range(n - 2):
        # Skip duplicates for the first element
        if i > 0 and l[i] == l[i - 1]:
            continue

        # Use two pointers for the remaining elements
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1

    return False

def change_base(x: int, base: int):
    if x == 0:
        return "0"
    digits = []
    while x:
        digits.append(str(x % base))
        x //= base
    return ''.join(reversed(digits))

def fib4(n: int):
    if n < 0:
        return 0
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Use dynamic programming to avoid recursion
    # We only need the last 4 values
    a, b, c, d = 0, 0, 2, 0  # fib4(0), fib4(1), fib4(2), fib4(3)

    for i in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d

