def fibfib(n: int):
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1

    # Use dynamic programming to avoid recalculating
    a, b, c = 0, 0, 1  # fibfib(0), fibfib(1), fibfib(2)
    for i in range(3, n + 1):
        next_val = a + b + c
        a, b, c = b, c, next_val

    return c

def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    else:
        return s[-shift:] + s[:-shift]

def pluck(arr):
    if not arr:
        return []

    smallest_even = None
    smallest_index = -1

    for i, val in enumerate(arr):
        if val % 2 == 0:  # even number
            if smallest_even is None or val < smallest_even:
                smallest_even = val
                smallest_index = i
            elif val == smallest_even and i < smallest_index:
                smallest_index = i

    if smallest_even is None:
        return []
    else:
        return [smallest_even, smallest_index]

def search(lst):
    from collections import Counter
    freq = Counter(lst)
    max_val = -1
    for num, count in freq.items():
        if num > 0 and count >= num:
            max_val = max(max_val, num)
    return max_val

def triangle_area(a, b, c):
    # Check if the three sides form a valid triangle
    if a + b > c and a + c > b and b + c > a:
        # Use Heron's formula to calculate the area
        s = (a + b + c) / 2
        area = (s * (s - a) * (s - b) * (s - c)) ** 0.5
        return round(area, 2)
    else:
        return -1

def will_it_fly(q, w):
    # Check if the list is balanced (palindromic)
    if q == q[::-1]:
        # Check if the sum of elements is less than or equal to w
        if sum(q) <= w:
            return True
    return False

def smallest_change(arr):
    n = len(arr)
    changes = 0
    # Compare elements from both ends moving inward
    for i in range(n // 2):
        if arr[i] != arr[n - 1 - i]:
            changes += 1
    return changes

def total_match(lst1, lst2):
    total_chars1 = sum(len(s) for s in lst1)
    total_chars2 = sum(len(s) for s in lst2)

    if total_chars1 < total_chars2:
        return lst1
    elif total_chars2 < total_chars1:
        return lst2
    else:
        return lst1

def is_multiply_prime(a):
    if a < 2:
        return False

    # Function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Find all prime factors
    factors = []
    temp = a
    for i in range(2, int(a**0.5) + 1):
        while temp % i == 0 and is_prime(i):
            factors.append(i)
            temp //= i

    # If temp is still greater than 1, it means it's a prime factor
    if temp > 1 and is_prime(temp):
        factors.append(temp)

    # Check if there are exactly 3 prime factors (not necessarily distinct)
    if len(factors) == 3:
        return True
    else:
        return False

def is_simple_power(x, n):
    if n == 1:
        return x == 1
    if n <= 0:
        return False
    if x == 1:
        return True
    if x < 1:
        return False

    # Check if x is a power of n
    power = 1
    while power < x:
        power *= n
        if power == x:
            return True
        if power > x:
            break

    return power == x

def iscube(a):
    if a < 0:
        a = -a
    root = round(a ** (1/3))
    return root ** 3 == a

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for digit in num:
        if digit in prime_hex_digits:
            count += 1
    return count

def decimal_to_binary(decimal):
    binary_str = bin(decimal)[2:]  # Convert to binary and remove '0b' prefix
    return "db" + binary_str + "db"

def is_happy(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] or s[i + 1] == s[i + 2] or s[i] == s[i + 2]:
            return False
    return True

def numerical_letter_grade(grades):
    letter_grades = []
    for grade in grades:
        if grade == 4.0:
            letter_grades.append('A+')
        elif grade > 3.7:
            letter_grades.append('A')
        elif grade > 3.3:
            letter_grades.append('A-')
        elif grade > 3.0:
            letter_grades.append('B+')
        elif grade > 2.7:
            letter_grades.append('B')
        elif grade > 2.3:
            letter_grades.append('B-')
        elif grade > 2.0:
            letter_grades.append('C+')
        elif grade > 1.7:
            letter_grades.append('C')
        elif grade > 1.3:
            letter_grades.append('C-')
        elif grade > 1.0:
            letter_grades.append('D+')
        elif grade > 0.7:
            letter_grades.append('D')
        elif grade > 0.0:
            letter_grades.append('D-')
        else:
            letter_grades.append('E')
    return letter_grades
